import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../../theme/kopitiam_theme.dart';
class WelcomeCoffeeMark extends StatefulWidget{const WelcomeCoffeeMark({super.key});@override State<WelcomeCoffeeMark> createState()=>_WelcomeCoffeeMarkState();}
class _WelcomeCoffeeMarkState extends State<WelcomeCoffeeMark> with SingleTickerProviderStateMixin{late final AnimationController _controller;late final Animation<double> _progress;@override void initState(){super.initState();_controller=AnimationController(vsync:this,duration:const Duration(milliseconds:1900));_progress=CurvedAnimation(parent:_controller,curve:const Cubic(.16,1,.3,1));if(!MediaQueryData.fromView(WidgetsBinding.instance.platformDispatcher.views.first).disableAnimations){_controller.forward();}else{_controller.value=1;}}@override void dispose(){_controller.dispose();super.dispose();}@override Widget build(BuildContext context)=>RepaintBoundary(child:SizedBox(key:const ValueKey('welcome-coffee-mark'),width:42,height:34,child:AnimatedBuilder(animation:_progress,builder:(_,__)=>CustomPaint(painter:_CoffeePainter(progress:_progress.value)))));}
class _CoffeePainter extends CustomPainter{final double progress;const _CoffeePainter({required this.progress});@override void paint(Canvas canvas,Size size){final paint=Paint()..color=KopitiamColors.yellow..style=PaintingStyle.stroke..strokeWidth=1.7..strokeCap=StrokeCap.round;final cup=RRect.fromRectAndCorners(Rect.fromLTWH(8,17,25,13),bottomLeft:const Radius.circular(8),bottomRight:const Radius.circular(8));canvas.drawRRect(cup,paint);canvas.drawArc(Rect.fromLTWH(31,19,9,9),-math.pi/2,math.pi,false,paint);canvas.drawLine(const Offset(4,32),const Offset(38,32),paint);final easedRise=1-math.pow(1-progress,3).toDouble(),settle=1-easedRise;paint.color=KopitiamColors.yellow.withValues(alpha:.58+settle*.18);for(var index=0;index<3;index++){final x=14.0+index*7,phase=(progress-index*.11).clamp(0.0,1.0),rise=1-math.pow(1-phase,3).toDouble();final path=Path()..moveTo(x+1.5,16-rise*2)..cubicTo(x-2,12-rise*3,x+3,8-rise*3,x,4-rise*2);canvas.drawPath(path,paint);}}@override bool shouldRepaint(covariant _CoffeePainter oldDelegate)=>oldDelegate.progress!=progress;}
